-- ============================================
-- MIGRATION SCRIPT
-- Alters existing tables to rename user/author columns to brand_id,
-- drops old FK constraints and indexes, creates new ones,
-- then inserts brand data and updates existing records.
-- ============================================

-- STEP 1: Drop old FK constraints
ALTER TABLE articles DROP CONSTRAINT IF EXISTS fk_article_author;
ALTER TABLE feedback DROP CONSTRAINT IF EXISTS fk_feedback_user;
ALTER TABLE search_history DROP CONSTRAINT IF EXISTS fk_search_user;

-- STEP 2: Drop old indexes
DROP INDEX IF EXISTS idx_articles_author;
DROP INDEX IF EXISTS idx_feedback_user;
DROP INDEX IF EXISTS idx_search_user;

ALTER TABLE articles DROP CONSTRAINT IF EXISTS fk_article_brand;
ALTER TABLE articles DROP COLUMN IF EXISTS brand_id;
ALTER TABLE articles DROP COLUMN IF EXISTS difficulty_level;
ALTER TABLE articles DROP COLUMN IF EXISTS read_time;
ALTER TABLE articles DROP COLUMN IF EXISTS view_count;
ALTER TABLE articles DROP COLUMN IF EXISTS author_id;
TRUNCATE TABLE articles CASCADE;
-- STEP 3: Rename columns
ALTER TABLE articles RENAME COLUMN author_id TO brand_id;
ALTER TABLE feedback RENAME COLUMN user_id TO brand_id;
ALTER TABLE search_history RENAME COLUMN user_id TO brand_id;

-- STEP 4: Drop users table (no longer needed)
DROP TABLE IF EXISTS users CASCADE;


-- ============================================
-- 1. BRANDS TABLE
-- ============================================
CREATE TABLE brands (
    id SERIAL PRIMARY KEY,
    brand_name VARCHAR(150) NOT NULL,
    industry VARCHAR(100),
    country_of_origin VARCHAR(100),
    founded_year INT,
    website VARCHAR(255),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_brands_slug ON brands(slug);
CREATE INDEX idx_brands_industry ON brands(industry);

-- ============================================
-- 2. CATEGORIES TABLE (Organization)
-- ============================================
CREATE TABLE categories (
    id SERIAL PRIMARY KEY,
    Category_name VARCHAR(150) NOT NULL,
    slug VARCHAR(150) UNIQUE NOT NULL,
    parent_id INT,
    description TEXT,
    icon VARCHAR(50),
    sort_order INT DEFAULT 0,
    is_active BOOLEAN DEFAULT TRUE,
    
    CONSTRAINT fk_parent_category
        FOREIGN KEY (parent_id)
        REFERENCES categories(id)
        ON DELETE SET NULL
);
CREATE INDEX idx_categories_parent ON categories(parent_id);
CREATE INDEX idx_categories_slug ON categories(slug);

-- ============================================
-- 3. PRODUCTS TABLE (Your Catalog)
-- ============================================
CREATE TABLE products(
    id SERIAL PRIMARY KEY,
    Product_name VARCHAR(255) NOT NULL,
    sku VARCHAR(100) UNIQUE NOT NULL,
    description TEXT,
    category_id INT NOT NULL,
    price DECIMAL(10,2) NOT NULL,
    discount_percentage DECIMAL(5,2) DEFAULT 0,
    specifications JSONB,
    images JSONB,
    status VARCHAR(50) CHECK (status IN ('available', 'out_of_stock', 'discontinued')) DEFAULT 'available',
    view_count INT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_product_category
        FOREIGN KEY (category_id)
        REFERENCES categories(id)
        ON DELETE RESTRICT
);
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_products_status ON products(status);
CREATE INDEX idx_products_sku ON products(sku);

-- ============================================
-- 4. ARTICLES TABLE (Help Content)
-- ============================================
CREATE TABLE articles (
    id SERIAL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    category_id INT NOT NULL,
    article_type VARCHAR(50) CHECK (article_type IN ('guide', 'troubleshooting', 'comparison', 'tutorial', 'best_practice')) NOT NULL,
    related_product_ids JSONB,
    brand_id INT,
    difficulty_level VARCHAR(20) CHECK (difficulty_level IN ('beginner', 'intermediate', 'advanced')) DEFAULT 'beginner',
    read_time INT, -- minutes
    view_count INT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_article_category
        FOREIGN KEY (category_id)
        REFERENCES categories(id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_article_brand
        FOREIGN KEY (brand_id)
        REFERENCES brands(id)
        ON DELETE SET NULL
);

CREATE INDEX idx_articles_category ON articles(category_id);
CREATE INDEX idx_articles_type ON articles(article_type);
CREATE INDEX idx_articles_brand ON articles(brand_id);
CREATE INDEX idx_articles_difficulty ON articles(difficulty_level);

-- ============================================
-- 5. FAQs TABLE (Quick Answers)
-- ============================================
CREATE TABLE faqs (
    id SERIAL PRIMARY KEY,
    question TEXT NOT NULL,
    answer TEXT NOT NULL,
    category_id INT NOT NULL,
    related_product_ids JSONB,
    related_article_ids JSONB,
    order_num INT DEFAULT 0,
    view_count INT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_faq_category
        FOREIGN KEY (category_id)
        REFERENCES categories(id)
        ON DELETE RESTRICT
);

CREATE INDEX idx_faqs_category ON faqs(category_id);
CREATE INDEX idx_faqs_order ON faqs(order_num);

-- ============================================
-- 6. FEEDBACK TABLE (Brand Input)
-- ============================================
CREATE TABLE feedback (
    id SERIAL PRIMARY KEY,
    brand_id INT,
    item_type VARCHAR(50) CHECK (item_type IN ('product', 'article', 'faq')) NOT NULL,
    item_id INT NOT NULL,
    rating_type VARCHAR(50) CHECK (rating_type IN ('helpful', 'star_rating', 'review')) NOT NULL,
    rating_value DECIMAL(3,2), -- For helpful: 1=yes, 0=no; For stars: 1-5
    comment TEXT,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    upvotes INT DEFAULT 0,
    status VARCHAR(50) CHECK (status IN ('approved', 'pending', 'rejected')) DEFAULT 'approved',
    metadata JSONB,
    
    CONSTRAINT fk_feedback_brand
        FOREIGN KEY (brand_id)
        REFERENCES brands(id)
        ON DELETE SET NULL
);

CREATE INDEX idx_feedback_item ON feedback(item_type, item_id);
CREATE INDEX idx_feedback_brand ON feedback(brand_id);
CREATE INDEX idx_feedback_timestamp ON feedback(timestamp DESC);

-- ============================================
-- 7. SEARCH HISTORY TABLE (Analytics)
-- ============================================
CREATE TABLE search_history (
    id SERIAL PRIMARY KEY,
    brand_id INT,
    search_query VARCHAR(500) NOT NULL,
    search_type VARCHAR(50) CHECK (search_type IN ('products', 'articles', 'all')) DEFAULT 'all',
    results_count INT DEFAULT 0,
    clicked_item_id INT,
    clicked_item_type VARCHAR(50),
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    session_id VARCHAR(100),
    found_helpful BOOLEAN,
    search_metadata JSONB,
    
    CONSTRAINT fk_search_brand
        FOREIGN KEY (brand_id)
        REFERENCES brands(id)
        ON DELETE SET NULL
);

CREATE INDEX idx_search_brand ON search_history(brand_id);
CREATE INDEX idx_search_query ON search_history(search_query);
CREATE INDEX idx_search_timestamp ON search_history(timestamp DESC);
CREATE INDEX idx_search_session ON search_history(session_id);
